/* tap setup, once: */
int tap[2];
socketpair(AF_UNIX, SOCK_SEQPACKET | SOCK_NONBLOCK, 0, tap);
/* fork(): child closes tap[0] and recv()s tap[1]; parent keeps tap[0] */

volatile size_t tap_dropped = 0;

int channel_send(int primary, int *tapfd, const void *buf, size_t len) {
    ssize_t w;
    do                                   /* primary: original, retry signals */
        w = send(primary, buf, len, 0);
    while (w < 0 && errno == EINTR);
    if (w < 0)
        return -1;
    if (send(*tapfd, buf, len, MSG_NOSIGNAL) < 0) {  /* copy: kernel-owned now */
        if (errno == EAGAIN || errno == EWOULDBLOCK)
            tap_dropped++;               /* explicit loss policy: drop + count */
        else if (errno == EPIPE)
            close(*tapfd), *tapfd = -1;  /* analyzer left: detach the tap */
    }
    return 0;
}
